/* Disposable Linux/glibc diagnostic only. Never loaded into production.
 * Counts successful malloc/calloc/realloc and frees in the marked interval;
 * aligned allocator families and internal libc allocations are not covered.
 */
#include <stddef.h>
#include <stdint.h>
#include <stdatomic.h>
extern void *__libc_malloc(size_t);
extern void *__libc_calloc(size_t, size_t);
extern void *__libc_realloc(void *, size_t);
extern void __libc_free(void *);
static _Atomic uint64_t enabled, calls, bytes, releases, caller_calls, caller_bytes;
static _Thread_local unsigned caller_scope;
void allocation_probe_enter_caller(void) { caller_scope = 1; }
void allocation_probe_leave_caller(void) { caller_scope = 0; }
static void note(void *pointer, size_t size) {
    if (pointer && atomic_load_explicit(&enabled, memory_order_relaxed)) {
        atomic_fetch_add_explicit(&calls, 1, memory_order_relaxed);
        atomic_fetch_add_explicit(&bytes, size, memory_order_relaxed);
        if (caller_scope) {
            atomic_fetch_add_explicit(&caller_calls, 1, memory_order_relaxed);
            atomic_fetch_add_explicit(&caller_bytes, size, memory_order_relaxed);
        }
    }
}
void *malloc(size_t size) { void *p = __libc_malloc(size); note(p, size); return p; }
void *calloc(size_t count, size_t size) { void *p = __libc_calloc(count, size); note(p, count * size); return p; }
void *realloc(void *old, size_t size) { void *p = __libc_realloc(old, size); note(p, size); return p; }
void free(void *pointer) {
    if (pointer && atomic_load_explicit(&enabled, memory_order_relaxed))
        atomic_fetch_add_explicit(&releases, 1, memory_order_relaxed);
    __libc_free(pointer);
}
void allocation_probe_begin(void) {
    atomic_store_explicit(&calls, 0, memory_order_relaxed);
    atomic_store_explicit(&bytes, 0, memory_order_relaxed);
    atomic_store_explicit(&releases, 0, memory_order_relaxed);
    atomic_store_explicit(&caller_calls, 0, memory_order_relaxed);
    atomic_store_explicit(&caller_bytes, 0, memory_order_relaxed);
    atomic_store_explicit(&enabled, 1, memory_order_relaxed);
}
void allocation_probe_end(uint64_t *out) {
    atomic_store_explicit(&enabled, 0, memory_order_relaxed);
    out[0] = atomic_load_explicit(&calls, memory_order_relaxed);
    out[1] = atomic_load_explicit(&bytes, memory_order_relaxed);
    out[2] = atomic_load_explicit(&releases, memory_order_relaxed);
    out[3] = atomic_load_explicit(&caller_calls, memory_order_relaxed);
    out[4] = atomic_load_explicit(&caller_bytes, memory_order_relaxed);
}

