// Diagnostic only: real native record.get calls without Python/GIL cost.
// Seed and verify a strict disposable authority; every timed result is exact.
#include <atomic>
#include <chrono>
#include <condition_variable>
#include <cstring>
#include <dlfcn.h>
#include <iostream>
#include <mutex>
#include <stdexcept>
#include <string>
#include <thread>
#include <vector>
#include <algorithm>
#include <time.h>
#include <cstdint>
using Clock = std::chrono::steady_clock;
using Open = void* (*)(const char*, uint64_t, int64_t, const char*, uint8_t*, size_t, uint8_t*, size_t);
using Execute = intptr_t (*)(void*, const uint8_t*, size_t, uint8_t*, size_t);
using Close = void (*)(void*);
using Identify = intptr_t (*)(uint8_t*, size_t);
double cpu_time() { timespec t{}; clock_gettime(CLOCK_PROCESS_CPUTIME_ID, &t); return t.tv_sec + t.tv_nsec/1e9; }
int main(int argc, char** argv) {
    if (argc != 3) return 2;
    auto allocation_begin = reinterpret_cast<void (*)()>(dlsym(RTLD_DEFAULT, "allocation_probe_begin"));
    auto enter_caller = reinterpret_cast<void (*)()>(dlsym(RTLD_DEFAULT, "allocation_probe_enter_caller"));
    auto leave_caller = reinterpret_cast<void (*)()>(dlsym(RTLD_DEFAULT, "allocation_probe_leave_caller"));
    auto allocation_end = reinterpret_cast<void (*)(uint64_t*)>(dlsym(RTLD_DEFAULT, "allocation_probe_end"));
    if (!allocation_begin || !allocation_end || !enter_caller || !leave_caller) throw std::runtime_error("missing allocation probe");
    void* library = dlopen(argv[1], RTLD_NOW | RTLD_LOCAL);
    if (!library) throw std::runtime_error(dlerror());
    auto open = reinterpret_cast<Open>(dlsym(library, "tofudb_embed_open"));
    auto execute = reinterpret_cast<Execute>(dlsym(library, "tofudb_embed_execute"));
    auto close = reinterpret_cast<Close>(dlsym(library, "tofudb_embed_close"));
    auto identify = reinterpret_cast<Identify>(dlsym(library, "tofudb_embed_source_sha256"));
    if (!open || !execute || !close || !identify) throw std::runtime_error("missing native ABI symbol");
    uint8_t digest[64]; if (identify(digest, sizeof digest) != 64) return 3;
    std::cout << "SOURCE " << std::string(reinterpret_cast<char*>(digest), 64) << std::endl;
    uint8_t secret[] = "worker-delivery-native-benchmark-01";
    uint8_t error[4096]{};
    void* handle = open(argv[2], 11, 7, nullptr, secret, sizeof secret-1, error, sizeof error);
    if (!handle) throw std::runtime_error(reinterpret_cast<char*>(error));
    auto deadline = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count() + 600000;
    auto envelope = [&](const std::string& operation, const std::string& payload, const std::string& command="null") {
        return "{\"operation\":\""+operation+"\",\"payload\":"+payload+",\"command_id\":"+command+",\"deadline_unix_ms\":"+std::to_string(deadline)+"}";
    };
    std::vector<uint8_t> buffer(1 << 20);
    auto invoke = [&](const std::string& request) {
        auto length = execute(handle, reinterpret_cast<const uint8_t*>(request.data()), request.size(), buffer.data(), buffer.size());
        if (length < 0 || size_t(length) > buffer.size()) throw std::runtime_error("native buffer/transport error");
        return std::string(reinterpret_cast<char*>(buffer.data()), length);
    };
    auto seeded = invoke(envelope("record.put", "{\"namespace\":\"native-benchmark\",\"key\":\"k\",\"value\":1,\"user_id\":11}", "\"seed\""));
    if (seeded.find("\"status\":0") == std::string::npos) throw std::runtime_error(seeded);
    auto request = envelope("record.get", "{\"namespace\":\"native-benchmark\",\"key\":\"k\",\"user_id\":11}");
    auto expected = invoke(request);
    if (expected.find("\"status\":0") == std::string::npos) throw std::runtime_error(expected);
    std::cout << "REFERENCE " << expected << std::endl;
    std::cout << "storage,callers,exact_readbacks,mean_ns,p50_ns,p99_ns,ops_per_second,cpu_seconds,wall_seconds" << std::endl;
    for (std::string storage : {"overlay", "materialized"}) {
    if (storage == "materialized") {
        close(handle);
        uint8_t fresh_secret[] = "worker-delivery-native-benchmark-01";
        handle = open(argv[2], 11, 7, nullptr, fresh_secret, sizeof fresh_secret-1, error, sizeof error);
        if (!handle) throw std::runtime_error(reinterpret_cast<char*>(error));
        if (invoke(request) != expected) throw std::runtime_error("materialized readback changed");
    }
    for (size_t callers : {1}) {
        size_t iterations = callers == 1 ? 100000 : (callers == 8 ? 12500 : 4000);
        std::mutex gate; std::condition_variable ready;
        size_t arrived=0; bool start=false;
        std::vector<std::vector<uint64_t>> measurements(callers);
        std::vector<std::thread> threads;
        for (size_t caller=0; caller<callers; ++caller) {
            threads.emplace_back([&, caller] {
                std::vector<uint8_t> output(1 << 20);
                auto read = [&] {
                    auto length = execute(handle, reinterpret_cast<const uint8_t*>(request.data()), request.size(), output.data(), output.size());
                    if (length != intptr_t(expected.size()) || std::memcmp(output.data(), expected.data(), expected.size())) {
                        throw std::runtime_error("native record.get readback changed");
                    }
                };
                for (int warm=0; warm<100; ++warm) read();
                { std::unique_lock<std::mutex> lock(gate); ++arrived; ready.notify_all(); ready.wait(lock, [&]{ return start; }); }
                auto& times=measurements[caller]; times.reserve(iterations);
                for (size_t ordinal=0; ordinal<iterations; ++ordinal) {
                    auto before=Clock::now();
                    enter_caller();
                    auto length=execute(handle, reinterpret_cast<const uint8_t*>(request.data()), request.size(), output.data(), output.size());
                    leave_caller();
                    times.push_back(std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-before).count());
                    if (length != intptr_t(expected.size()) || std::memcmp(output.data(), expected.data(), expected.size())) throw std::runtime_error("inexact timed readback");
                }
            });
        }
        std::unique_lock<std::mutex> lock(gate); ready.wait(lock, [&]{ return arrived==callers; });
        allocation_begin(); auto before=Clock::now(); auto cpu=cpu_time(); start=true; lock.unlock(); ready.notify_all();
        for (auto& thread:threads) thread.join();
        uint64_t allocation_counts[5]; allocation_end(allocation_counts);
        std::cout << "ALLOCATIONS " << storage << " " << allocation_counts[0] << " " << allocation_counts[1] << " " << allocation_counts[2] << " " << allocation_counts[3] << " " << allocation_counts[4] << std::endl;
        auto wall=std::chrono::duration<double>(Clock::now()-before).count(); cpu=cpu_time()-cpu;
        std::vector<uint64_t> times;
        for (auto& row:measurements) times.insert(times.end(), row.begin(), row.end());
        std::sort(times.begin(), times.end()); double sum=0; for(auto time:times) sum+=time;
        std::cout << storage << ',' << callers << ',' << times.size() << ',' << sum/times.size() << ',' << times[times.size()/2] << ',' << times[times.size()*99/100] << ',' << times.size()/wall << ',' << cpu << ',' << wall << std::endl;
    }
    }
    auto metrics=invoke(envelope("system.metrics", "{}"));
    if(metrics.find("\"walDurability\":\"strict\"")==std::string::npos) throw std::runtime_error("durability policy changed");
    close(handle);
    // The ABI intentionally detaches execute workers. Keep their code mapped
    // until this isolated measurement process exits; do not dlclose early.
}

